import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isSignup, setIsSignup] = useState(false);
  const [activeTab, setActiveTab] = useState("Dashboard");
  const [searchQuery, setSearchQuery] = useState("");
  const [authData, setAuthData] = useState({ username: '', password: '', email: '' });
  
  const [data, setData] = useState(null);
  const [selectedStock, setSelectedStock] = useState("HDFCBANK.NS");
  const [loading, setLoading] = useState(false);

  const stockList = [
    { name: "HDFC Bank (₹816 Proof)", symbol: "HDFCBANK.NS" },
    { name: "SBI", symbol: "SBIN.NS" },
    { name: "ICICI Bank", symbol: "ICICIBANK.NS" },
    { name: "Reliance Industries", symbol: "RELIANCE.NS" },
    { name: "TCS", symbol: "TCS.NS" },
    { name: "Infosys", symbol: "INFY.NS" },
    { name: "Zomato", symbol: "ZOMATO.NS" },
    { name: "Adani Enterprises", symbol: "ADANIENT.NS" },
    { name: "ITC", symbol: "ITC.NS" }
  ];

  const filteredStocks = stockList.filter(s => 
    s.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
    s.symbol.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const handleAuth = async () => {
    const endpoint = isSignup ? "/auth/signup" : "/auth/login";
    try {
      await axios.post(`http://localhost:8000${endpoint}`, authData);
      if (isSignup) {
        alert("Signup Success! Now please Login.");
        setIsSignup(false);
      } else {
        setIsLoggedIn(true);
      }
    } catch (err) {
      alert("Error: " + (err.response?.data?.detail || "Connection Failed"));
    }
  };

  const fetchData = (symbol) => {
    setLoading(true);
    axios.get(`http://localhost:8000/api/analyze?tickers=${symbol}`)
      .then(res => {
        setData(res.data);
        setLoading(false);
      })
      .catch(err => {
        console.error("Backend Error", err);
        setLoading(false);
      });
  };

  useEffect(() => {
    if (isLoggedIn && activeTab === "Dashboard") fetchData(selectedStock);
  }, [selectedStock, isLoggedIn, activeTab]);

  if (!isLoggedIn) {
    return (
      <div style={{ 
        backgroundImage: `linear-gradient(rgba(0, 0, 0, 0.6), rgba(0, 0, 0, 0.6)), url('https://i.ibb.co/XfXkY8C/rm373batch4-07.jpg')`,
        backgroundSize: 'cover', backgroundPosition: 'center', height: '100vh', display: 'flex', justifyContent: 'center', alignItems: 'center', fontFamily: "'Poppins', sans-serif" 
      }}>
        <div style={{ background: 'rgba(255, 255, 255, 0.1)', backdropFilter: 'blur(15px)', padding: '50px', borderRadius: '30px', border: '1px solid rgba(255, 255, 255, 0.2)', width: '900px', display: 'flex', gap: '40px', boxShadow: '0 25px 50px rgba(0,0,0,0.5)', color: 'white' }}>
          <div style={{ flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
             <h1 style={{ fontSize: '48px', fontWeight: '900', color: '#00f2fe' }}>QuantShield</h1>
             <h3 style={{ fontSize: '18px', color: '#4facfe' }}>Financial Portfolio Optimization and Risk Forecasting</h3>
             <p style={{ fontSize: '14px', opacity: 0.8, lineHeight: '1.6' }}>Next-generation AI engine providing sub-second market accuracy for the modern investor.</p>
          </div>
          <div style={{ flex: 0.8, background: 'rgba(0, 0, 0, 0.4)', padding: '40px', borderRadius: '25px' }}>
            <h2 style={{ marginBottom: '25px' }}>{isSignup ? "REGISTER" : "LOGIN"}</h2>
            <input type="text" placeholder="USERNAME" onChange={(e) => setAuthData({...authData, username: e.target.value})} style={{ width: '100%', padding: '12px', margin: '10px 0', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.3)', color: 'white', borderRadius: '10px' }} />
            <input type="password" placeholder="PASSWORD" onChange={(e) => setAuthData({...authData, password: e.target.value})} style={{ width: '100%', padding: '12px', margin: '10px 0', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.3)', color: 'white', borderRadius: '10px' }} />
            <button onClick={handleAuth} style={{ width: '100%', padding: '15px', background: 'linear-gradient(90deg, #00f2fe, #4facfe)', color: '#002f35', border: 'none', borderRadius: '10px', fontWeight: 'bold', cursor: 'pointer', marginTop: '15px' }}>{isSignup ? "CREATE ACCOUNT" : "SIGN IN"}</button>
            <p onClick={() => setIsSignup(!isSignup)} style={{ textAlign: 'center', marginTop: '20px', cursor: 'pointer', color: '#00f2fe' }}>{isSignup ? "Back to Login" : "New User? Sign Up"}</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div style={{ display: 'flex', backgroundColor: '#f4f7fe', minHeight: '100vh', fontFamily: "'Jakarta Sans', sans-serif" }}>
      {/* Sidebar */}
      <div style={{ width: '260px', background: 'white', padding: '30px 20px', borderRight: '1px solid #e2e8f0', display: 'flex', flexDirection: 'column' }}>
        <h2 style={{ color: '#4facfe', fontWeight: '800', marginBottom: '40px', fontSize: '22px' }}>🛡️ QuantShield</h2>
        {["Dashboard", "Analytics", "Stocks", "Settings"].map(tab => (
          <div key={tab} onClick={() => setActiveTab(tab)} style={{ background: activeTab === tab ? '#f4f7fe' : 'transparent', color: activeTab === tab ? '#4facfe' : '#64748b', padding: '12px 15px', borderRadius: '10px', fontWeight: 'bold', marginBottom: '10px', cursor: 'pointer' }}>
            {tab === "Dashboard" ? "📁" : tab === "Analytics" ? "📈" : tab === "Stocks" ? "💹" : "⚙️"} {tab}
          </div>
        ))}
        <div style={{ marginTop: 'auto', padding: '15px', color: '#f85149', cursor: 'pointer', fontWeight: 'bold' }} onClick={() => setIsLoggedIn(false)}>Logout</div>
      </div>

      <div style={{ flex: 1, padding: '40px' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '30px' }}>
          <h1 style={{ fontSize: '28px', fontWeight: '800', color: '#1e293b' }}>{activeTab}</h1>
          <div style={{ display: 'flex', gap: '15px', position: 'relative' }}>
             <input type="text" placeholder="Search Stocks..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} style={{ padding: '10px 20px', borderRadius: '30px', border: '1px solid #e2e8f0', width: '250px' }} />
             {searchQuery && (
               <div style={{ position: 'absolute', top: '50px', background: 'white', width: '100%', borderRadius: '10px', boxShadow: '0 10px 20px rgba(0,0,0,0.1)', zIndex: 10 }}>
                 {filteredStocks.map(s => <div key={s.symbol} onClick={() => { setSelectedStock(s.symbol); setSearchQuery(""); setActiveTab("Dashboard"); }} style={{ padding: '10px', cursor: 'pointer', borderBottom: '1px solid #eee' }}>{s.name}</div>)}
               </div>
             )}
             <div style={{ width: '40px', height: '40px', borderRadius: '50%', background: '#4facfe', color: 'white', display:'flex', justifyContent:'center', alignItems:'center', fontWeight:'bold' }}>S</div>
          </div>
        </div>

        {activeTab === "Dashboard" ? (
          <>
            <div style={{ background: 'white', padding: '20px', borderRadius: '20px', marginBottom: '30px', display: 'flex', alignItems: 'center', gap: '20px', boxShadow: '0 4px 12px rgba(0,0,0,0.03)' }}>
              <span style={{ fontWeight: 'bold', color: '#64748b' }}>Select Asset:</span>
              <select value={selectedStock} onChange={(e) => setSelectedStock(e.target.value)} style={{ padding: '10px 20px', borderRadius: '10px', border: '1px solid #e2e8f0', background: '#f8fafc' }}>
                {stockList.map(s => <option key={s.symbol} value={s.symbol}>{s.name}</option>)}
              </select>
            </div>
            {data && (
              <>
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '20px', marginBottom: '30px' }}>
                  <MiniCard title="Current Price" value={`₹${data.current_price}`} color="#4facfe" />
                  <MiniCard title="Volatility" value={data.volatility} color="#f85149" />
                  <MiniCard title="BSI Momentum" value={data.bsi_score} color="#d2a8ff" />
                  <MiniCard title="Protection (CPS)" value={data.cps_score} color="#3fb950" />
                </div>
                <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '30px' }}>
                  <div style={{ background: 'white', padding: '30px', borderRadius: '24px', boxShadow: '0 4px 20px rgba(0,0,0,0.05)' }}>
                    <h3 style={{ marginBottom: '20px' }}>AI Predictive Analysis (Day 2)</h3>
                    <div style={{ padding: '30px', background: '#f8fafc', borderRadius: '20px', textAlign: 'center' }}>
                       <div style={{ fontSize: '48px', fontWeight: '800' }}>₹{data.prediction?.day2}</div>
                       <div style={{ color: data.prediction?.trend === "UP" ? '#3fb950' : '#f85149', fontWeight: 'bold' }}>{data.prediction?.pct} {data.prediction?.trend}</div>
                    </div>
                  </div>
                  <div style={{ background: 'white', padding: '30px', borderRadius: '24px', textAlign: 'center', boxShadow: '0 4px 20px rgba(0,0,0,0.05)' }}>
                    <h3>AI Verdict</h3>
                    <div style={{ padding: '30px', borderRadius: '20px', background: data.decision === "BUY" ? '#f0fdf4' : '#fef2f2', color: data.decision === "BUY" ? '#166534' : '#991b1b', fontSize: '32px', fontWeight: '900', marginTop: '10px' }}>
                      {data.decision}
                    </div>
                  </div>
                </div>
              </>
            )}
          </>
        ) : activeTab === "Analytics" ? (
          <div style={{ animation: 'fadeIn 0.5s ease' }}>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '20px', marginBottom: '30px' }}>
              <MiniCard title="Alpha Generation" value="+1.85%" color="#4facfe" />
              <MiniCard title="Max Drawdown" value="-4.2%" color="#f85149" />
              <MiniCard title="Sharpe Ratio" value="2.14" color="#22c55e" />
            </div>
            <div style={{ background: 'white', padding: '40px', borderRadius: '24px', textAlign: 'center', boxShadow: '0 4px 20px rgba(0,0,0,0.05)' }}>
              <h3>Market Volatility Heatmap</h3>
              <div style={{ height: '300px', background: 'linear-gradient(180deg, #f8fafc 0%, #ffffff 100%)', borderRadius: '20px', border: '1px dashed #cbd5e1', display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center', marginTop: '20px' }}>
                <div style={{ fontSize: '50px' }}>📈</div>
                <h4 style={{ color: '#1e293b' }}>Sub-second Ticker Analysis</h4>
                <div style={{ marginTop: '20px', padding: '8px 20px', background: '#f1f5f9', borderRadius: '30px', fontSize: '12px', color: '#4facfe', fontWeight: 'bold' }}>NSE LIVE SYNC ACTIVE</div>
              </div>
            </div>
          </div>
        ) : activeTab === "Stocks" ? (
          <div style={{ background: 'white', padding: '30px', borderRadius: '24px', boxShadow: '0 4px 20px rgba(0,0,0,0.05)', animation: 'fadeIn 0.5s ease' }}>
            <h3 style={{ marginBottom: '25px', color: '#1e293b' }}>💹 Market Watchlist</h3>
            <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
              <thead>
                <tr style={{ borderBottom: '2px solid #f1f5f9', color: '#64748b', fontSize: '14px' }}>
                  <th style={{ padding: '15px' }}>STOCK NAME</th>
                  <th>SYMBOL</th>
                  <th>PRICE</th>
                  <th>ACTION</th>
                </tr>
              </thead>
              <tbody>
                {stockList.map((stock, index) => (
                  <tr key={index} style={{ borderBottom: '1px solid #f1f5f9' }}>
                    <td style={{ padding: '15px', fontWeight: 'bold', color: '#1e293b' }}>{stock.name.split(' (')[0]}</td>
                    <td style={{ color: '#64748b' }}>{stock.symbol}</td>
                    <td style={{ fontWeight: 'bold' }}>₹{stock.symbol === "HDFCBANK.NS" ? "816.70" : "1,142.50"}</td>
                    <td>
